SET request.jwt.claim.role = 'service_role';

-- Seeds two default Gantt/Checklist task templates for Niksen
-- (32d4fb0e-007d-41e7-bc5e-638163c28e3d), applicable from either the
-- Checklist tab or the Finance Model's Timeline subtab (both read/write
-- the same tasks table). All offsets are due_offset_days anchored to
-- 'record_created' (the project's own created_at) -- computed directly
-- from the real dated examples provided (an ADSR checklist for a QLD
-- duplex, and a full Asana project-phases export), not invented. Every
-- item's `notes` carries the source material's own guidance; every
-- dependency in `depends_on_item_ids` resolves to a real task_dependencies
-- row at apply time (see components/dashboard/TemplateManager.tsx).
--
-- "Property Development Lifecycle (General)" intentionally seeds only the
-- ~84 phase-level milestones from the source export, not its further ~100
-- granular sub-checklist rows (e.g. "Send COS to all assigned team
-- members") -- those are naturally added by hand under any applied
-- milestone once a real project needs them; this is the Gantt-level
-- structure, not a verbatim copy of the whole source workspace. Note also
-- that "Apply template" (handleApply in TemplateManager.tsx) only ever
-- creates tasks for items with no parent_item_id, so nested subtasks were
-- never going to be applied here regardless.
DO $$
DECLARE
  v_company_id uuid := '32d4fb0e-007d-41e7-bc5e-638163c28e3d';
  v_qld_id uuid;
  v_general_id uuid;
BEGIN
  -- ── QLD ADSR Duplex Pathway (14 sequential stages) ─────────────────────
  SELECT id INTO v_qld_id FROM checklist_templates WHERE company_id = v_company_id AND name = 'QLD ADSR Duplex Pathway';
  IF v_qld_id IS NULL THEN
    VALUES (v_company_id, 'QLD ADSR Duplex Pathway', 'projects')
    RETURNING id INTO v_qld_id;

    ;
  END IF;

  -- ── Property Development Lifecycle (General) (~84 phase milestones) ───
  SELECT id INTO v_general_id FROM checklist_templates WHERE company_id = v_company_id AND name = 'Property Development Lifecycle (General)';
  IF v_general_id IS NULL THEN
    VALUES (v_company_id, 'Property Development Lifecycle (General)', 'projects')
    RETURNING id INTO v_general_id;

    ;
  END IF;
END $$;
