    INSERT INTO checklist_templates (company_id, name, record_table)
    INSERT INTO checklist_template_items (id, template_id, display_order, title, due_offset_days, due_anchor, depends_on_item_ids, notes) VALUES
    ('c7e966a9-376a-46c5-a1cb-4fefa1697f00'::uuid, v_qld_id, 0, 'DD: Feasibility & Planning Check', 0, 'record_created', NULL::uuid[], 'Responsible: TPA (Town Planner). Review zoning, overlays, flood risk and site constraints to identify the planning pathway (ADSR vs full DA).'),
    ('87939b28-445b-4ab9-a5d7-b437a99f7b66'::uuid, v_qld_id, 1, 'Detail & Contour Survey', 14, 'record_created', ARRAY['c7e966a9-376a-46c5-a1cb-4fefa1697f00'::uuid]::uuid[], 'Responsible: BP&S (Surveyor). Boundary, topography, sewer, stormwater and existing dwelling survey -- provides the accurate base for design.'),
    ('1de4528e-e4a2-41e4-ad21-c920ff39f95d'::uuid, v_qld_id, 2, 'Concept Design (for Planning Compliance)', 35, 'record_created', ARRAY['87939b28-445b-4ab9-a5d7-b437a99f7b66'::uuid]::uuid[], 'Responsible: Designer. Site plan, floor plan, elevations, parking and setbacks -- concept drawings ready for planner review.'),
    ('c2f02941-1678-42c8-a200-eb633c3c0b99'::uuid, v_qld_id, 3, 'Planning Compliance / Exemption', 49, 'record_created', ARRAY['1de4528e-e4a2-41e4-ad21-c920ff39f95d'::uuid]::uuid[], 'Responsible: TPA (Town Planner). ADSR Code Compliance Report or Exemption Certificate confirming the project qualifies for ADSR (no full DA needed).'),
    ('652091f2-ed94-4955-9125-fdcb1a74a8e2'::uuid, v_qld_id, 4, 'Flood Assessment', 63, 'record_created', ARRAY['c2f02941-1678-42c8-a200-eb633c3c0b99'::uuid]::uuid[], 'Responsible: Flood Engineer. Flood memo for Council to obtain the Flood Exemption Certificate.'),
    ('c6d4e5b8-d788-4c39-affa-afbdb50cf1c3'::uuid, v_qld_id, 5, 'Building Design Development', 84, 'record_created', ARRAY['652091f2-ed94-4955-9125-fdcb1a74a8e2'::uuid]::uuid[], 'Responsible: Designer. Structural, civil and energy documentation prepared for the Building Approval (BA) application.'),
    ('acccab20-6262-4c27-84e0-7a4fec5f7741'::uuid, v_qld_id, 6, 'Engineer + Energy Assessor', 98, 'record_created', ARRAY['c6d4e5b8-d788-4c39-affa-afbdb50cf1c3'::uuid]::uuid[], 'Responsible: Engineer, Energy Assessor. Engineering and energy-rating reports feeding into BA documentation.'),
    ('02ae0f8c-fa10-4e74-8a55-419e08e9c5d8'::uuid, v_qld_id, 7, 'Building Approval (BA)', 119, 'record_created', ARRAY['acccab20-6262-4c27-84e0-7a4fec5f7741'::uuid]::uuid[], 'Responsible: Certifier. Certifier reviews and issues the Building Development Approval permit.'),
    ('20f6a9f2-fe70-4bdf-ab8f-1aae7f35c678'::uuid, v_qld_id, 8, 'Construction', 209, 'record_created', ARRAY['02ae0f8c-fa10-4e74-8a55-419e08e9c5d8'::uuid]::uuid[], 'Responsible: Builder. Build the dwellings; certifier inspects at each stage.'),
    ('26362dc7-e409-4b4c-922e-4758be507505'::uuid, v_qld_id, 9, 'Inspections', 216, 'record_created', ARRAY['20f6a9f2-fe70-4bdf-ab8f-1aae7f35c678'::uuid]::uuid[], 'Responsible: Certifier. Stage inspections culminating in the Form 21 Final Inspection Certificate.'),
    ('2bbcc0ae-0f19-40c0-ac21-611eb9c127a1'::uuid, v_qld_id, 10, 'Final Survey (BFP, EUA, SLD)', 230, 'record_created', ARRAY['26362dc7-e409-4b4c-922e-4758be507505'::uuid]::uuid[], 'Responsible: BP&S (Surveyor). As-built survey (Building Format Plan, Easement/Utility Advice, Survey Lot Diagram) -- technical plans for plan sealing.'),
    ('db37f500-5904-4764-a750-a342a5f39abc'::uuid, v_qld_id, 11, 'Plan Sealing / ExpressSeal', 251, 'record_created', ARRAY['2bbcc0ae-0f19-40c0-ac21-611eb9c127a1'::uuid]::uuid[], 'Responsible: TPA (Town Planner). Lodge plan sealing with Council for the Council-sealed plan.'),
    ('76021846-5f80-40cf-a8e4-9e902ac71d97'::uuid, v_qld_id, 12, 'Council Fees', 258, 'record_created', ARRAY['db37f500-5904-4764-a750-a342a5f39abc'::uuid]::uuid[], 'Responsible: Council (paid via TPA). Plan sealing and CMS endorsement fees.'),
    ('8c472237-b889-4d80-8ed2-cc26251ebc2d'::uuid, v_qld_id, 13, 'CMS & Title Registration', 279, 'record_created', ARRAY['76021846-5f80-40cf-a8e4-9e902ac71d97'::uuid]::uuid[], 'Responsible: Solicitor. Prepare the Community Management Statement and lodge with Titles QLD -- issues the new strata titles.')
    INSERT INTO checklist_templates (company_id, name, record_table)
    INSERT INTO checklist_template_items (id, template_id, display_order, title, due_offset_days, due_anchor, depends_on_item_ids, notes) VALUES
    ('585b6da4-5797-4d26-8ebb-d2e5e29da816'::uuid, v_general_id, 0, 'Signed Contract of Sale (COS) acquired', 0, 'record_created', NULL::uuid[], 'Phase: Acquisition. Responsible: Multiple Teams. First milestone that kicks off the project. Initial buyer is often a placeholder entity (e.g. Niksen Time Pty Ltd). Watch for Nomination Clause, Settlement Condition Clauses, and (QLD) early insurance requirements.'),
    ('4a9a3bb5-d41a-44ea-8dc6-2bbe4464f9f2'::uuid, v_general_id, 1, 'Development Planning and Tasks Scheduling and Assigning Project Owner', 5, 'record_created', ARRAY['585b6da4-5797-4d26-8ebb-d2e5e29da816'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Lending. Determine and communicate development plan, feasibility, expected costs and timeline; assign the Project Owner.'),
    ('3a584a63-43b2-42ea-99cd-2c942ef1469e'::uuid, v_general_id, 2, 'Project Owner''s Preparation', 55, 'record_created', ARRAY['4a9a3bb5-d41a-44ea-8dc6-2bbe4464f9f2'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Project Owner. Project Owner maps out tasks for the whole timeline guided by the Feasibility Report; lists internal/external contacts per phase.'),
    ('a0364b92-02d9-4699-af56-b145db7b2174'::uuid, v_general_id, 3, 'Initial Deposit Paid', 16, 'record_created', ARRAY['585b6da4-5797-4d26-8ebb-d2e5e29da816'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Multiple Teams. Deposit payment date/amount on the COS is not the source of truth -- it can be negotiated. Lending needs the correct remitted amount for the loan application.'),
    ('de97351e-741c-46d1-9a15-73a99ee47b26'::uuid, v_general_id, 4, 'Outstanding Deposit Paid (Full)', 27, 'record_created', ARRAY['a0364b92-02d9-4699-af56-b145db7b2174'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Project Owner. May not exist if fully paid at Initial Deposit, or can be delayed to Settlement as part of funds to complete.'),
    ('5f01eef8-6846-4385-8456-f8edbf1eb4b7'::uuid, v_general_id, 5, 'Building and Pest Inspection', 43, 'record_created', ARRAY['de97351e-741c-46d1-9a15-73a99ee47b26'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Project Owner. Last date to complete building and pest inspection -- affects price negotiation and avoids unexpected repair costs.'),
    ('e2cb7c50-e4a4-45ed-896a-2a656b54787e'::uuid, v_general_id, 6, 'Lending Planning and Application Preparation', 31, 'record_created', ARRAY['4a9a3bb5-d41a-44ea-8dc6-2bbe4464f9f2'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Lending. Mortgage broker decides borrowing entity structure and guarantor, considering serviceability, sub-cost/construction estimates, and lender options.'),
    ('facabbae-c718-4ab1-9e5f-ce55fafec3e3'::uuid, v_general_id, 7, 'Loan Application Lodged', 33, 'record_created', ARRAY['e2cb7c50-e4a4-45ed-896a-2a656b54787e'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Lending. Track each lender''s SLA closely -- turnaround time is a key factor in lender choice, not just rate.'),
    ('7e7a5f57-0dd4-4560-bc63-74ab29ac317b'::uuid, v_general_id, 8, 'Conditional Approval', 48, 'record_created', ARRAY['facabbae-c718-4ab1-9e5f-ce55fafec3e3'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Lending. Lender requests additional documents/conditions before Unconditional Offer; goal is to minimise this duration.'),
    ('f7380b5d-8d0d-463c-9972-ec082351df7b'::uuid, v_general_id, 9, 'Unconditional Offer Acquired', 63, 'record_created', ARRAY['7e7a5f57-0dd4-4560-bc63-74ab29ac317b'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Lending. Complete loan docs ASAP, arrange CoC insurance if required, initiate discharge with outgoing lender if refinance, notify solicitor for Finance Clause deadline.'),
    ('266797b3-21ae-48d2-862a-f333720ae51a'::uuid, v_general_id, 10, 'Finance Date', 59, 'record_created', ARRAY['5f01eef8-6846-4385-8456-f8edbf1eb4b7'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Lending. Date the buyer must have finance in place per the Finance Clause -- can be negotiated/extended/removed.'),
    ('6c66ae6f-6e26-46bb-9124-6edc8946bc2f'::uuid, v_general_id, 11, 'Unconditional Date', 68, 'record_created', ARRAY['266797b3-21ae-48d2-862a-f333720ae51a'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Project Owner. Past this date the buyer cannot recover the deposit.'),
    ('81efdafb-80c5-43c4-b156-8a61b5d7a739'::uuid, v_general_id, 12, 'Settlement conditions fulfilled (for the purchase and the loan)', 76, 'record_created', ARRAY['f7380b5d-8d0d-463c-9972-ec082351df7b'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Multiple Teams. Distinct from loan settlement conditions -- can include B&P negotiated repairs, DA permit, separate titles, demolition.'),
    ('ef2b7864-4b0c-402f-82f5-640db840d5e4'::uuid, v_general_id, 13, 'Settlement Date', 80, 'record_created', ARRAY['81efdafb-80c5-43c4-b156-8a61b5d7a739'::uuid,'6c66ae6f-6e26-46bb-9124-6edc8946bc2f'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Multiple Teams. Carried out via PEXA Workspace. Cash flow: buyer funds + incoming lender loan -> outgoing lender paid out -> fees paid -> excess to vendor.'),
    ('2004bdc4-3d2e-4a54-aed3-e9fd6199b265'::uuid, v_general_id, 14, 'Post Settlement Tasks', 106, 'record_created', ARRAY['ef2b7864-4b0c-402f-82f5-640db840d5e4'::uuid]::uuid[], 'Phase: Acquisition. Responsible: Multiple Teams. Lending/legal to send loan details, Funds to Complete breakdown and PEXA documents to accounting for reconciliation.'),
    ('8fadb8c1-bc0a-4f5a-bd40-918c8f20f46e'::uuid, v_general_id, 15, 'Contact Town Planner for consultation', 5, 'record_created', ARRAY['585b6da4-5797-4d26-8ebb-d2e5e29da816'::uuid]::uuid[], 'Phase: Development Approval Stage. Responsible: Project Owner. Outcome: a concrete development trajectory -- required assessments, compliance documents, parties and fees. Contact ASAP; should be clear before the Unconditional Date.'),
    ('91ae0adb-a1bd-4ba1-bad5-be831d5324e3'::uuid, v_general_id, 16, 'Contact Surveyor', 71, 'record_created', ARRAY['8fadb8c1-bc0a-4f5a-bd40-918c8f20f46e'::uuid]::uuid[], 'Phase: Development Approval Stage. Responsible: Project Owner. Boundary, topography, sewer, stormwater and existing survey -- provides the accurate base case for design.'),
    ('9af736cf-8da3-4db0-8e2e-1fa325d3c7da'::uuid, v_general_id, 17, 'Town Planning Compliance Report Acquired', 75, 'record_created', ARRAY['91ae0adb-a1bd-4ba1-bad5-be831d5324e3'::uuid]::uuid[], 'Phase: Development Approval Stage. Responsible: Project Owner. Development Compliance Report or Exemption Certificate confirming the chosen pathway (e.g. ADSR).'),
    ('a7939304-4562-48f8-bde6-fd07e1704e7e'::uuid, v_general_id, 18, 'Contact Architect and relevant Contractors for Development Design', 102, 'record_created', ARRAY['9af736cf-8da3-4db0-8e2e-1fa325d3c7da'::uuid]::uuid[], 'Phase: Development Approval Stage. Responsible: Project Owner. Contractors mandated by the Development Proposal (architect, flood/energy/soil assessor, engineer, etc). Subdivision can occur pre- or post-construction depending on scenario.'),
    ('3eb8d54b-a8af-46b8-86a9-7a10bcde3c00'::uuid, v_general_id, 19, 'Finalized Development Plan and Requirements', 104, 'record_created', ARRAY['a7939304-4562-48f8-bde6-fd07e1704e7e'::uuid]::uuid[], 'Phase: Development Approval Stage. Responsible: Multiple Teams. Project officially moves to the Building Approval process from here.'),
    ('0dfb041d-3713-4f6e-b1f9-47247cead389'::uuid, v_general_id, 20, 'Development Application Lodged / Notify Council and or State as per Compliance Report requirements', 112, 'record_created', ARRAY['3eb8d54b-a8af-46b8-86a9-7a10bcde3c00'::uuid]::uuid[], 'Phase: Development Approval Stage. Responsible: Multiple Teams.'),
    ('679972ce-165e-4de3-8cd4-3f1d74d1fbf1'::uuid, v_general_id, 21, 'Development Approval Acquired', 121, 'record_created', ARRAY['0dfb041d-3713-4f6e-b1f9-47247cead389'::uuid]::uuid[], 'Phase: Development Approval Stage. Responsible: Multiple Teams. Important prerequisite milestone enabling construction; deliverable is the DA permit.'),
    ('f842da6c-db41-4478-b35d-9b7966100c01'::uuid, v_general_id, 22, 'Contact with Builder and Supplier for quote and negotiations', 118, 'record_created', ARRAY['3eb8d54b-a8af-46b8-86a9-7a10bcde3c00'::uuid]::uuid[], 'Phase: Building Approval Stage. Responsible: Project Owner. Engage the builder ASAP to expedite BA -- some builders can run the BA process for you.'),
    ('a2dc5bfe-7f03-4531-873e-be52ea6a90d8'::uuid, v_general_id, 23, 'Contact Certifier to start assessments and application for Building Approval permit', 120, 'record_created', ARRAY['3eb8d54b-a8af-46b8-86a9-7a10bcde3c00'::uuid]::uuid[], 'Phase: Building Approval Stage. Responsible: Project Owner. Certifier assesses and applies for BA with the relevant authority; will flag any extra adjustments/exemptions needed.'),
    ('c1ad558a-62f2-4799-9fc7-4855e5f687c1'::uuid, v_general_id, 24, 'Builder Quote Acquired', 120, 'record_created', ARRAY['f842da6c-db41-4478-b35d-9b7966100c01'::uuid]::uuid[], 'Phase: Building Approval Stage. Responsible: Builder (External).'),
    ('fb12e238-4be8-4801-9926-a5bc99f555e9'::uuid, v_general_id, 25, 'Building Approval Application Lodged', 122, 'record_created', ARRAY['f842da6c-db41-4478-b35d-9b7966100c01'::uuid,'a2dc5bfe-7f03-4531-873e-be52ea6a90d8'::uuid]::uuid[], 'Phase: Building Approval Stage. Responsible: Multiple Teams. BA permit is issued against a specific DA permit AND a specific builder plan -- different builders can have different plans for the same DA.'),
    ('781d0c54-640c-4df9-8f59-21f803788066'::uuid, v_general_id, 26, 'Building Approval Permit Acquired', 131, 'record_created', ARRAY['fb12e238-4be8-4801-9926-a5bc99f555e9'::uuid,'6749f7fd-2116-4b3b-8942-de41a0ce46d9'::uuid]::uuid[], 'Phase: Building Approval Stage. Responsible: Project Owner. Milestone that enables construction to begin. An executed Building Contract can be settled with the BA Permit as its condition.'),
    ('3b7e16f1-97d6-4514-a7a1-545a9f67f930'::uuid, v_general_id, 27, 'Construction Loan Application Research and Documentation Preparation', 141, 'record_created', ARRAY['c1ad558a-62f2-4799-9fc7-4855e5f687c1'::uuid]::uuid[], 'Phase: Construction. Responsible: Lending. Consider building contract price limit, lender type, entity/guarantor viability, funds to complete, drawdown process, and GRV vs Cost-of-Construction lending (GRV: 65% LVR, 2yr term, no serviceability; Cost of Construction: 80% LVR, 30yr term, serviceability mandatory).'),
    ('6749f7fd-2116-4b3b-8942-de41a0ce46d9'::uuid, v_general_id, 28, 'Building Contract Acquired and Executed', 123, 'record_created', ARRAY['c1ad558a-62f2-4799-9fc7-4855e5f687c1'::uuid]::uuid[], 'Phase: Construction. Responsible: Builder (External). Must come with Builder Insurance -- forward both the executed contract and insurance to the mortgage broker; some lenders want these at lodgement.'),
    ('f9b014f8-f504-4ca6-b690-a7eb01eb9c2f'::uuid, v_general_id, 29, 'Construction Loan Application Lodged', 144, 'record_created', ARRAY['3b7e16f1-97d6-4514-a7a1-545a9f67f930'::uuid,'6749f7fd-2116-4b3b-8942-de41a0ce46d9'::uuid]::uuid[], 'Phase: Construction. Responsible: Lending.'),
    ('cf514944-cea1-46d9-9fa0-70012a4db5a8'::uuid, v_general_id, 30, 'Deposit Paid for Building Contract', 148, 'record_created', ARRAY['6749f7fd-2116-4b3b-8942-de41a0ce46d9'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner. Deposit is typically 5-10% of the contract price -- lenders can consider a contract ''front-loaded'' if Deposit >5% or Base Stage >10% (e.g. Firstmac).'),
    ('fa1a8cdc-c135-4a25-a40b-e635d7258128'::uuid, v_general_id, 31, 'Construction Loan Conditional Approval', 151, 'record_created', ARRAY['f9b014f8-f504-4ca6-b690-a7eb01eb9c2f'::uuid]::uuid[], 'Phase: Construction. Responsible: Lending. Expected conditions: executed Building Contract, DA Permit, sometimes proof of funds to complete, and a construction valuation report.'),
    ('bde36c9b-9a6f-450b-9e2a-5f857ae952f4'::uuid, v_general_id, 32, 'Base Stage Construction', 169, 'record_created', ARRAY['cf514944-cea1-46d9-9fa0-70012a4db5a8'::uuid]::uuid[], 'Phase: Construction. Responsible: Builder (External).'),
    ('8163f9c1-678c-4ddd-8f1a-f25b6eefd89f'::uuid, v_general_id, 33, 'Construction Loan Unconditional Approval', 156, 'record_created', ARRAY['fa1a8cdc-c135-4a25-a40b-e635d7258128'::uuid]::uuid[], 'Phase: Construction. Responsible: Lending. Complete loan docs, acquire CoC, initiate discharge if refinance/cash out, provide BA and DA permits.'),
    ('0f151a32-6658-4feb-b3c4-455c2a35f68e'::uuid, v_general_id, 34, 'Base Stage Invoice Issued', 168, 'record_created', ARRAY['bde36c9b-9a6f-450b-9e2a-5f857ae952f4'::uuid]::uuid[], 'Phase: Construction. Responsible: Multiple Teams. Arrange payment, guarantor signature, send signed invoice + remittance to lender, liaise with site manager for QS valuation.'),
    ('53fb8be7-f192-4e72-adf2-f56731828477'::uuid, v_general_id, 35, 'Base Stage Invoice Paid', 172, 'record_created', ARRAY['0f151a32-6658-4feb-b3c4-455c2a35f68e'::uuid,'bde36c9b-9a6f-450b-9e2a-5f857ae952f4'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner. Deposit/Base Stage invoices often have to be paid from the developer''s own equity before Construction Loan Settlement, then reimbursed via first drawdown.'),
    ('efaec306-d749-4832-af4c-d67a1f9927bc'::uuid, v_general_id, 36, 'Base Stage Valuation Completed = Mandatory', 174, 'record_created', ARRAY['53fb8be7-f192-4e72-adf2-f56731828477'::uuid]::uuid[], 'Phase: Construction. Responsible: Lending. QS report mandatory at Base and Practical Completion stages for most lenders (some, e.g. La Trobe, require it every stage).'),
    ('357b5ff5-866d-414e-9010-8fd9026b4d45'::uuid, v_general_id, 37, 'Settlement for Construction Loan', 162, 'record_created', ARRAY['8163f9c1-678c-4ddd-8f1a-f25b6eefd89f'::uuid]::uuid[], 'Phase: Construction. Responsible: Multiple Teams. Nominate the Project Owner as borrowing-entity representative post settlement for direct lender liaison on drawdowns.'),
    ('22bc1a41-d654-461d-b80d-4e28be379493'::uuid, v_general_id, 38, 'First Loan Drawdown for Base Stage', 183, 'record_created', ARRAY['53fb8be7-f192-4e72-adf2-f56731828477'::uuid,'efaec306-d749-4832-af4c-d67a1f9927bc'::uuid,'cf514944-cea1-46d9-9fa0-70012a4db5a8'::uuid]::uuid[], 'Phase: Construction. Responsible: Multiple Teams. Construction loan balance is $0 at settlement and increases as drawn -- interest is calculated on the drawn balance, not the full facility.'),
    ('02081f36-f094-4b08-b803-53e6b3d6bb57'::uuid, v_general_id, 39, 'Framing Stage', 191, 'record_created', ARRAY['bde36c9b-9a6f-450b-9e2a-5f857ae952f4'::uuid]::uuid[], 'Phase: Construction. Responsible: Builder (External).'),
    ('e2253098-c361-470c-a112-2ff2e80b929f'::uuid, v_general_id, 40, 'Framing Stage Invoice Issued', 194, 'record_created', ARRAY['02081f36-f094-4b08-b803-53e6b3d6bb57'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner.'),
    ('cb53e8e2-61d1-41c2-85fd-0b9cd0ff0f63'::uuid, v_general_id, 41, 'Framing Stage Loan Drawdown', 197, 'record_created', ARRAY['e2253098-c361-470c-a112-2ff2e80b929f'::uuid,'22bc1a41-d654-461d-b80d-4e28be379493'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner. Most lenders skip a QS report per-stage, but some (e.g. La Trobe) require one every stage.'),
    ('56e784d7-f129-4628-af45-1f06bae22d68'::uuid, v_general_id, 42, 'Lock Up Stage', 220, 'record_created', ARRAY['02081f36-f094-4b08-b803-53e6b3d6bb57'::uuid]::uuid[], 'Phase: Construction. Responsible: Builder (External).'),
    ('37147fdf-f5dc-49d7-9425-62c0e41063de'::uuid, v_general_id, 43, 'Lock Up Stage Invoice Issued', 222, 'record_created', ARRAY['56e784d7-f129-4628-af45-1f06bae22d68'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner.'),
    ('8bddea50-3c23-4d46-b7fe-784c3b67d41d'::uuid, v_general_id, 44, 'Lock Up Stage Loan Drawdown', 226, 'record_created', ARRAY['37147fdf-f5dc-49d7-9425-62c0e41063de'::uuid,'cb53e8e2-61d1-41c2-85fd-0b9cd0ff0f63'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner.'),
    ('7f895e23-30a5-4b9e-9836-da003d2e5924'::uuid, v_general_id, 45, 'Fixing Stage', 249, 'record_created', ARRAY['56e784d7-f129-4628-af45-1f06bae22d68'::uuid]::uuid[], 'Phase: Construction. Responsible: Builder (External).'),
    ('b081c777-8048-4c9d-936a-437f2d5853c9'::uuid, v_general_id, 46, 'Fixing Stage Invoice Issued', 250, 'record_created', ARRAY['7f895e23-30a5-4b9e-9836-da003d2e5924'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner.'),
    ('e26ff8d6-4d20-45c3-895b-9abb8179670a'::uuid, v_general_id, 47, 'Fixing Stage Loan Drawdown', 252, 'record_created', ARRAY['b081c777-8048-4c9d-936a-437f2d5853c9'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner.'),
    ('ceb7c312-5b2d-4401-8b2b-2a3fa11032e6'::uuid, v_general_id, 48, 'Practical Completion', 266, 'record_created', ARRAY['7f895e23-30a5-4b9e-9836-da003d2e5924'::uuid]::uuid[], 'Phase: Construction. Responsible: Builder (External).'),
    ('66553d4d-32a3-41b6-8f7c-504f1dcbb5cc'::uuid, v_general_id, 49, 'Practical Completion Stage Invoice Issued', 268, 'record_created', ARRAY['ceb7c312-5b2d-4401-8b2b-2a3fa11032e6'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner.'),
    ('853880d4-53a0-412b-94b3-7a972d04ec8e'::uuid, v_general_id, 50, 'Practical Completion Valuation = Mandatory', 280, 'record_created', ARRAY['ceb7c312-5b2d-4401-8b2b-2a3fa11032e6'::uuid]::uuid[], 'Phase: Construction. Responsible: Project Owner. Project Owner liaises with the lender''s QS and builder''s site manager to arrange the inspection/valuation.'),
    ('ccf7dda1-ff7f-47f5-9e75-9590761705a1'::uuid, v_general_id, 51, 'Practical Completion Stage Loan Drawdown', 301, 'record_created', ARRAY['66553d4d-32a3-41b6-8f7c-504f1dcbb5cc'::uuid,'853880d4-53a0-412b-94b3-7a972d04ec8e'::uuid,'cc7d120f-bb38-401c-af28-f635d0e2fcf3'::uuid]::uuid[], 'Phase: Construction. Responsible: Multiple Teams. First and last construction stages always require a valuation/QS report before drawdown release, which extends the invoice-to-payment period.'),
    ('eb36ac0a-17f1-4771-985b-0f135d35df07'::uuid, v_general_id, 52, 'Land Scaping Early Tasks', 155, 'record_created', ARRAY['679972ce-165e-4de3-8cd4-3f1d74d1fbf1'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Project Owner. Check which landscaping items are included in the building contract; record each item''s own start-to-finish schedule. Not considered Operational Works.'),
    ('82053a83-e874-4ee2-8d37-5122f845cfb6'::uuid, v_general_id, 53, 'Land Scaping Later Tasks', 296, 'record_created', ARRAY['eb36ac0a-17f1-4771-985b-0f135d35df07'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Project Owner. Deadline depends on outcome needed -- open home, price negotiation, cash flow, or COS Settlement.'),
    ('b5a0dfed-85fe-4b7a-9daf-c3c7b3b93d96'::uuid, v_general_id, 54, 'Final Survey - by Surveyor', 296, 'record_created', ARRAY['ceb7c312-5b2d-4401-8b2b-2a3fa11032e6'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Multiple Teams. As-built survey (BFP, EUA, SLD) -- prerequisite for plan sealing.'),
    ('3be95359-6388-4bf6-a7c6-990cfddd9516'::uuid, v_general_id, 55, 'Final Inspection - by Certifier', 296, 'record_created', ARRAY['ceb7c312-5b2d-4401-8b2b-2a3fa11032e6'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Multiple Teams. Deliverable is the Final Inspection Certificate (QLD: Form 21).'),
    ('cc7d120f-bb38-401c-af28-f635d0e2fcf3'::uuid, v_general_id, 56, 'Occupational Certificate (OC) Acquired', 298, 'record_created', ARRAY['3be95359-6388-4bf6-a7c6-990cfddd9516'::uuid,'b5a0dfed-85fe-4b7a-9daf-c3c7b3b93d96'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Builder (External). Legal confirmation the dwelling is safe to occupy -- mandatory before occupation, and a prerequisite for Practical Completion drawdown.'),
    ('694a8fcc-d760-4166-b5e1-b7f455fe1ada'::uuid, v_general_id, 57, 'Plan Sealing', 317, 'record_created', ARRAY['b5a0dfed-85fe-4b7a-9daf-c3c7b3b93d96'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Project Owner. Lodge plan sealing application with Council using the Final Survey Plan.'),
    ('b8ce4b93-07f3-4f86-94e5-1336f011e1b8'::uuid, v_general_id, 58, 'Council Contribution Payment', 317, 'record_created', ARRAY['b5a0dfed-85fe-4b7a-9daf-c3c7b3b93d96'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Project Owner. Mandatory local-authority contribution -- amount varies by council/state.'),
    ('46dced81-7e53-42cd-aea4-91581a98a976'::uuid, v_general_id, 59, 'New Title/s Issued', 336, 'record_created', ARRAY['694a8fcc-d760-4166-b5e1-b7f455fe1ada'::uuid,'b8ce4b93-07f3-4f86-94e5-1336f011e1b8'::uuid]::uuid[], 'Phase: Post-Construction Stage. Responsible: Multiple Teams. Each dwelling needs its own title (Torrens or Strata) before separate sale -- mandatory settlement condition. Notify the outgoing lender for loan discharge; security value needs revaluation/refinance once titles split.'),
    ('6ddeb71f-26fc-4dcc-a3c8-29860d4a0c4f'::uuid, v_general_id, 60, 'Off-the plan Sale Advertisement', 171, 'record_created', ARRAY['bde36c9b-9a6f-450b-9e2a-5f857ae952f4'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Sales Agent and Project Owner. Off-the-plan sale/advertisement can start at early construction stages to gauge demand and support pricing.'),
    ('0debbfff-d608-4b3d-a7c4-75ad8cb23948'::uuid, v_general_id, 61, 'Post Construction Sale Advertisement', 298, 'record_created', ARRAY['cc7d120f-bb38-401c-af28-f635d0e2fcf3'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Sales Agent and Project Owner. Normal property sale advertisement post-OC.'),
    ('62363607-8f95-4424-8a50-86262099c936'::uuid, v_general_id, 62, 'Home Inspections Start', 303, 'record_created', ARRAY['82053a83-e874-4ee2-8d37-5122f845cfb6'::uuid,'eb36ac0a-17f1-4771-985b-0f135d35df07'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Sales Agent and Project Owner. Same milestones as acquisition, roles reversed (now the vendor). Leased properties need property-manager liaison for inspection windows.'),
    ('7842518b-9948-4ce7-a2ae-b1349499491c'::uuid, v_general_id, 63, 'Under Contract (Contract Exchanged)', 317, 'record_created', ARRAY['62363607-8f95-4424-8a50-86262099c936'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Sales Agent and Project Owner. COS is evidence for the lending team to initiate discharge with the current lender.'),
    ('24671c62-7f40-4150-bb12-2ca349a8c23b'::uuid, v_general_id, 64, 'Initial Deposit Paid', 328, 'record_created', ARRAY['7842518b-9948-4ce7-a2ae-b1349499491c'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Multiple Teams. Held in the solicitor''s trust account -- vendor normally doesn''t receive it until Settlement.'),
    ('1a5a15fb-9880-479b-8b3d-e9d217d2b1d8'::uuid, v_general_id, 65, 'Cooling Off Period Expired', 339, 'record_created', ARRAY['24671c62-7f40-4150-bb12-2ca349a8c23b'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Project Owner. 3-5 business days depending on state; buyer can exit for a 0.25% penalty. Can be negotiated away for a firmer commitment.'),
    ('65fe711c-98e5-4105-b61a-8bbbadfa2e5c'::uuid, v_general_id, 66, 'Building and Pest Deadline', 349, 'record_created', ARRAY['1a5a15fb-9880-479b-8b3d-e9d217d2b1d8'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Multiple Teams. Last date for the buyer''s building and pest inspection -- can affect price/negotiation and delay settlement.'),
    ('4d01a194-216f-46ac-999a-46f9b77108d9'::uuid, v_general_id, 67, 'Finance Date Expiry', 360, 'record_created', ARRAY['65fe711c-98e5-4105-b61a-8bbbadfa2e5c'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Legal. Buyer''s date to have finance in place per the Finance Clause.'),
    ('df8d24fc-33d0-4589-8e0d-720877944662'::uuid, v_general_id, 68, 'Unconditional Date', 367, 'record_created', ARRAY['4d01a194-216f-46ac-999a-46f9b77108d9'::uuid,'46dced81-7e53-42cd-aea4-91581a98a976'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Legal. Past this date the buyer cannot recover their deposit.'),
    ('13ba1bd7-9380-42ee-b5cc-62f1914af797'::uuid, v_general_id, 69, 'Loan Discharge Process', 377, 'record_created', ARRAY['cc7d120f-bb38-401c-af28-f635d0e2fcf3'::uuid,'46dced81-7e53-42cd-aea4-91581a98a976'::uuid,'7842518b-9948-4ce7-a2ae-b1349499491c'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Lending. Requires OC acquired, new titles issued, and an executed buyer COS. Maximise the retained loan amount against any unsold dwelling kept as collateral.'),
    ('41112a9b-6d00-41c2-a934-2c0657b03192'::uuid, v_general_id, 70, 'Settlement Date', 379, 'record_created', ARRAY['df8d24fc-33d0-4589-8e0d-720877944662'::uuid,'13ba1bd7-9380-42ee-b5cc-62f1914af797'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Multiple Teams. As vendor, this is where the project profit is realised -- solicitor oversees PEXA to ensure correct payout.'),
    ('a0ff4ecc-b830-459d-90d2-eb5306aa35df'::uuid, v_general_id, 71, 'Post Settlement', 393, 'record_created', ARRAY['41112a9b-6d00-41c2-a934-2c0657b03192'::uuid]::uuid[], 'Phase: Sale (External Buyer). Responsible: Multiple Teams. Lending/legal send loan details, agreement and payout figures to accounting for reconciliation; cancel scheduled interest repayments.'),
    ('fc11e687-3ec9-4cce-adc7-f0987f64a758'::uuid, v_general_id, 72, 'Refinance Preparation & Research', 295, 'record_created', ARRAY['66553d4d-32a3-41b6-8f7c-504f1dcbb5cc'::uuid]::uuid[], 'Phase: Cash Out via Refinance or Internal Sale. Responsible: Lending. Consider cash-out outcome, partial vs full discharge, entity/guarantor viability given the now much higher combined security value -- may need new guarantors or an internal sale (5% stamp duty cost).'),
    ('c830a30a-faae-41ab-8ddf-2374dfa40a92'::uuid, v_general_id, 73, 'Refinance/Cash Out Application Lodged', 305, 'record_created', ARRAY['fc11e687-3ec9-4cce-adc7-f0987f64a758'::uuid,'ccf7dda1-ff7f-47f5-9e75-9590761705a1'::uuid]::uuid[], 'Phase: Cash Out via Refinance or Internal Sale. Responsible: Lending. Clarify borrowing entity, outgoing lender and incoming lender and their legal representatives.'),
    ('086827bb-2095-4e9d-963b-ece58149d64b'::uuid, v_general_id, 74, 'Refinance Conditional Approval', 317, 'record_created', ARRAY['cc7d120f-bb38-401c-af28-f635d0e2fcf3'::uuid]::uuid[], 'Phase: Cash Out via Refinance or Internal Sale. Responsible: Lending. Push to Unconditional Approval ASAP once conditional.'),
    ('f787d5b1-1941-41d4-92fd-eafa87fbb795'::uuid, v_general_id, 75, 'Refinance Unconditional Approval', 332, 'record_created', ARRAY['086827bb-2095-4e9d-963b-ece58149d64b'::uuid]::uuid[], 'Phase: Cash Out via Refinance or Internal Sale. Responsible: Lending. Very specific settlement conditions -- e.g. outgoing lender paid in full and account closed, certified new titles provided.'),
    ('90f0684b-506f-4829-9b12-af27cb3b17c2'::uuid, v_general_id, 76, 'Loan Discharge Process and Complications', 352, 'record_created', ARRAY['f787d5b1-1941-41d4-92fd-eafa87fbb795'::uuid,'46dced81-7e53-42cd-aea4-91581a98a976'::uuid]::uuid[], 'Phase: Cash Out via Refinance or Internal Sale. Responsible: Lending. Payout/shortfall figures can be highly complex when only some dwellings sell -- clarify with the legal team well ahead of settlement.'),
    ('44b77f40-c490-47f3-9bd9-eb3cafa431e6'::uuid, v_general_id, 77, 'Refinance Settlement Date', 356, 'record_created', ARRAY['f787d5b1-1941-41d4-92fd-eafa87fbb795'::uuid,'90f0684b-506f-4829-9b12-af27cb3b17c2'::uuid,'46dced81-7e53-42cd-aea4-91581a98a976'::uuid]::uuid[], 'Phase: Cash Out via Refinance or Internal Sale. Responsible: Multiple Teams. Legal team oversees PEXA to ensure correct payout to the vendor entity.'),
    ('f8a8d474-e706-4d1e-8a9f-6a6450eb0692'::uuid, v_general_id, 78, 'Refinance Post Settlement', 374, 'record_created', ARRAY['44b77f40-c490-47f3-9bd9-eb3cafa431e6'::uuid]::uuid[], 'Phase: Cash Out via Refinance or Internal Sale. Responsible: Multiple Teams. Lending/legal provide loan details, agreement and payout figures to accounting; set up periodic interest repayment if applicable.'),
    ('656086ad-6449-4ff0-b0b6-0bbf46dade9a'::uuid, v_general_id, 79, 'Money Partner Deal discussion and negotiation', 126, 'record_created', NULL::uuid[], 'Phase: Money Partner Equity Injection. Responsible: Multiple Teams. Can start at any time. Higher risk should mean higher reward -- consider loan amount, term, equity injection timing, and collateralisation via registerable mortgage. Payout structures: fixed interest (10-15%) or profit sharing (pro-rata to equity input, higher upside but tied to Profit Before Tax).'),
    ('ad3b855f-786f-4081-bde9-33dbf014bff3'::uuid, v_general_id, 80, 'Money Partner Loan Agreement Signed', 128, 'record_created', ARRAY['656086ad-6449-4ff0-b0b6-0bbf46dade9a'::uuid]::uuid[], 'Phase: Money Partner Equity Injection. Responsible: Multiple Teams. Legal document formalising the agreement -- no one template fits all money partner deals; may include a Registerable Mortgage Form and Pay Out Figure Schedule.'),
    ('bb472b7a-438c-45ab-821d-7e5f849fe20a'::uuid, v_general_id, 81, 'Agreed Principal Funds transfer to Niksen Time Pty Ltd', 136, 'record_created', ARRAY['ad3b855f-786f-4081-bde9-33dbf014bff3'::uuid]::uuid[], 'Phase: Money Partner Equity Injection. Responsible: Multiple Teams. Funds transfer to Niksen Time Pty Ltd''s account -- accounting reconciles and prepares the pay-out schedule in Xero.'),
    ('ed990e7c-1d26-4793-b41d-60ade66bc9a0'::uuid, v_general_id, 82, 'Money Partner Pay Out Condition/s met', 157, 'record_created', ARRAY['bb472b7a-438c-45ab-821d-7e5f849fe20a'::uuid]::uuid[], 'Phase: Money Partner Equity Injection. Responsible: Multiple Teams. Triggers: early withdrawal request, loan term expiry, or registerable mortgage needing to move (e.g. refinance requiring a clean title).'),
    ('7fe920de-57af-40b9-8207-b20f2b125e32'::uuid, v_general_id, 83, 'Money Partner Pay Out post Project Completion', 170, 'record_created', ARRAY['ed990e7c-1d26-4793-b41d-60ade66bc9a0'::uuid]::uuid[], 'Phase: Money Partner Equity Injection. Responsible: Multiple Teams. Eventually the money partner must be paid out in full -- track principal vs interest vs profit-share components and payment method for tax/cashflow purposes.')
